-- =====================================================================
-- ReconFlow — initial schema (PostgreSQL 16)
--
-- Conventions
--   * Primary keys are UUIDv7, generated by the application.
--     PostgreSQL 16 has no built-in uuidv7() (it arrives in 18), so
--     there are deliberately no DEFAULTs on id columns.
--   * Every tenant-owned table carries organization_id, including child
--     tables, so row-level security (M3.5) and tenant-leading indexes work.
--   * Money is NUMERIC(19,4). Never float.
--   * Statuses are TEXT + CHECK rather than ENUM types: adding a value is
--     a one-line constraint change instead of an ALTER TYPE.
--   * Timestamps are TIMESTAMPTZ. updated_at is maintained by the
--     application (@UpdateTimestamp), not by triggers.
--   * PostgreSQL does not index foreign-key columns automatically; each
--     FK that is queried or joined on has an explicit index below.
--
-- Not in this file (added by later migrations)
--   * Row-level security policies (M3.5)
--   * Separate migration / application DB roles (M10.7)
-- =====================================================================


-- ---------------------------------------------------------------------
-- 1. Users and tenancy
-- ---------------------------------------------------------------------

CREATE TABLE organization (
    id          UUID        PRIMARY KEY,
    name        TEXT        NOT NULL,
    status      TEXT        NOT NULL DEFAULT 'ACTIVE'
                            CHECK (status IN ('ACTIVE', 'SUSPENDED')),
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- A user is global, not owned by one organization: membership links
-- them to one or more organizations, each with its own role.
CREATE TABLE app_user (
    id                    UUID        PRIMARY KEY,
    email                 TEXT        NOT NULL,
    display_name          TEXT        NOT NULL,
    password_hash         TEXT        NOT NULL,   -- DelegatingPasswordEncoder format, e.g. {bcrypt}$2a$...
    is_platform_admin     BOOLEAN     NOT NULL DEFAULT FALSE,
    status                TEXT        NOT NULL DEFAULT 'ACTIVE'
                                      CHECK (status IN ('ACTIVE', 'LOCKED', 'DISABLED')),
    must_change_password  BOOLEAN     NOT NULL DEFAULT TRUE,
    failed_login_count    INT         NOT NULL DEFAULT 0 CHECK (failed_login_count >= 0),
    locked_until          TIMESTAMPTZ,
    last_login_at         TIMESTAMPTZ,
    created_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at            TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Case-insensitive uniqueness without the citext extension.
-- Look users up with WHERE lower(email) = lower(:email) to use this index.
CREATE UNIQUE INDEX app_user_email_uk ON app_user (lower(email));

CREATE TABLE membership (
    user_id          UUID        NOT NULL REFERENCES app_user (id),
    organization_id  UUID        NOT NULL REFERENCES organization (id),
    role             TEXT        NOT NULL
                                 CHECK (role IN ('ORG_ADMIN', 'INVESTIGATOR', 'UPLOADER', 'VIEWER')),
    created_by       UUID        REFERENCES app_user (id),   -- NULL only for seeded / bootstrap users
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, organization_id)
);

CREATE INDEX membership_org_idx ON membership (organization_id);

-- Only a hash of each refresh token is stored. family_id groups every
-- token descended from one login, so a reused (stolen) token can revoke
-- the whole family (M3.3c).
CREATE TABLE refresh_token (
    id           UUID        PRIMARY KEY,
    user_id      UUID        NOT NULL REFERENCES app_user (id),
    family_id    UUID        NOT NULL,
    token_hash   CHAR(64)    NOT NULL UNIQUE,                -- SHA-256 hex
    expires_at   TIMESTAMPTZ NOT NULL,
    revoked_at   TIMESTAMPTZ,
    replaced_by  UUID        REFERENCES refresh_token (id),
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX refresh_token_family_idx ON refresh_token (family_id);
CREATE INDEX refresh_token_user_idx   ON refresh_token (user_id);


-- ---------------------------------------------------------------------
-- 2. Cross-cutting: audit log and job queue
-- ---------------------------------------------------------------------

CREATE TABLE audit_event (
    id               UUID        PRIMARY KEY,
    organization_id  UUID        REFERENCES organization (id), -- NULL for platform events, e.g. a failed login for an unknown email
    actor_id         UUID        REFERENCES app_user (id),     -- NULL for system actions (workers, sweeper)
    action           TEXT        NOT NULL,                     -- e.g. EXCEPTION_RESOLVED
    entity_type      TEXT        NOT NULL,                     -- e.g. EXCEPTION_CASE
    entity_id        UUID,
    payload          JSONB       NOT NULL DEFAULT '{}',
    request_id       TEXT,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX audit_event_entity_idx ON audit_event (organization_id, entity_type, entity_id, created_at);
CREATE INDEX audit_event_actor_idx  ON audit_event (organization_id, actor_id, created_at);

-- Append-only, enforced by the database rather than by convention.
-- Row triggers don't fire on TRUNCATE, so it gets a statement trigger too.
-- Integration tests must not TRUNCATE this table between tests.
CREATE FUNCTION audit_event_block_changes() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'audit_event is append-only: % is not allowed', TG_OP;
END;
$$;

CREATE TRIGGER audit_event_no_update_delete
    BEFORE UPDATE OR DELETE ON audit_event
    FOR EACH ROW EXECUTE FUNCTION audit_event_block_changes();

CREATE TRIGGER audit_event_no_truncate
    BEFORE TRUNCATE ON audit_event
    FOR EACH STATEMENT EXECUTE FUNCTION audit_event_block_changes();

-- Background jobs, claimed with SELECT ... FOR UPDATE SKIP LOCKED.
-- See docs/scalability.md §4.
CREATE TABLE job (
    id               UUID        PRIMARY KEY,
    organization_id  UUID        NOT NULL REFERENCES organization (id),
    type             TEXT        NOT NULL CHECK (type IN ('IMPORT', 'RECONCILE', 'EXPORT')),
    payload          JSONB       NOT NULL,
    status           TEXT        NOT NULL DEFAULT 'QUEUED'
                                 CHECK (status IN ('QUEUED', 'RUNNING', 'DONE', 'FAILED')),
    attempts         INT         NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    max_attempts     INT         NOT NULL DEFAULT 5 CHECK (max_attempts > 0),
    run_after        TIMESTAMPTZ NOT NULL DEFAULT now(),
    locked_by        TEXT,
    lease_until      TIMESTAMPTZ,
    last_error       TEXT,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (status <> 'RUNNING' OR (locked_by IS NOT NULL AND lease_until IS NOT NULL))
);

CREATE INDEX job_claim_idx       ON job (run_after, created_at) WHERE status = 'QUEUED';
CREATE INDEX job_running_org_idx ON job (organization_id)       WHERE status = 'RUNNING';  -- per-org fairness count
CREATE INDEX job_lease_idx       ON job (lease_until)           WHERE status = 'RUNNING';  -- expired-lease sweeper


-- ---------------------------------------------------------------------
-- 3. Ingestion
-- ---------------------------------------------------------------------

CREATE TABLE import_batch (
    id                  UUID        PRIMARY KEY,
    organization_id     UUID        NOT NULL REFERENCES organization (id),
    source_type         TEXT        NOT NULL CHECK (source_type IN ('INTERNAL_LEDGER', 'GATEWAY')),
    status              TEXT        NOT NULL DEFAULT 'RECEIVED'
                                    CHECK (status IN ('RECEIVED', 'PROCESSING', 'COMPLETED',
                                                      'COMPLETED_WITH_ERRORS', 'FAILED')),
    file_name           TEXT        NOT NULL,
    file_size_bytes     BIGINT      NOT NULL CHECK (file_size_bytes >= 0),
    content_hash        CHAR(64)    NOT NULL,                -- SHA-256 hex of the file bytes
    storage_key         TEXT        NOT NULL,                -- object-storage key of the original file
    total_rows          INT         NOT NULL DEFAULT 0 CHECK (total_rows >= 0),
    valid_rows          INT         NOT NULL DEFAULT 0 CHECK (valid_rows >= 0),
    error_rows          INT         NOT NULL DEFAULT 0 CHECK (error_rows >= 0),
    last_committed_row  INT         NOT NULL DEFAULT 0,      -- resume checkpoint for crashed imports
    failure_reason      TEXT,
    uploaded_by         UUID        NOT NULL REFERENCES app_user (id),
    started_at          TIMESTAMPTZ,
    completed_at        TIMESTAMPTZ,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (valid_rows + error_rows <= total_rows)
);

-- Duplicate-file detection. Revisit when the duplicate-import ADR (M1.12)
-- decides what a deliberate re-import looks like.
CREATE UNIQUE INDEX import_batch_content_uk ON import_batch (organization_id, source_type, content_hash);
CREATE INDEX import_batch_list_idx          ON import_batch (organization_id, created_at DESC);

CREATE TABLE import_row_error (
    id               UUID        PRIMARY KEY,
    organization_id  UUID        NOT NULL REFERENCES organization (id),
    batch_id         UUID        NOT NULL REFERENCES import_batch (id),
    row_number       INT         NOT NULL CHECK (row_number > 0),   -- 1-based, header excluded
    column_name      TEXT,                                          -- NULL for whole-row errors
    error_code       TEXT        NOT NULL,
    message          TEXT        NOT NULL,
    raw_row          TEXT,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    -- A retried import must not report the same error twice. NULLS NOT
    -- DISTINCT (PostgreSQL 15+) makes two NULL column_names collide.
    UNIQUE NULLS NOT DISTINCT (batch_id, row_number, column_name, error_code)
);

-- Normalized transactions from every source. Partitioned by month on
-- transaction_date (docs/scalability.md §5.1). PostgreSQL requires every
-- unique constraint on a partitioned table to include the partition key,
-- which is why transaction_date appears in the PK and in the unique key.
CREATE TABLE transaction_record (
    id                      UUID          NOT NULL,
    organization_id         UUID          NOT NULL REFERENCES organization (id),
    batch_id                UUID          NOT NULL REFERENCES import_batch (id),
    source_type             TEXT          NOT NULL CHECK (source_type IN ('INTERNAL_LEDGER', 'GATEWAY')),
    source_row_number       INT           NOT NULL CHECK (source_row_number > 0),
    raw_reference           TEXT          NOT NULL,
    normalized_reference    TEXT          NOT NULL,
    amount                  NUMERIC(19,4) NOT NULL,
    currency                CHAR(3)       NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),   -- ISO 4217
    transaction_type        TEXT          NOT NULL DEFAULT 'PAYMENT'
                                          CHECK (transaction_type IN ('PAYMENT', 'REFUND', 'CHARGEBACK', 'FEE')),
    status                  TEXT          NOT NULL
                                          CHECK (status IN ('SUCCESS', 'PENDING', 'FAILED', 'REVERSED')),
    transaction_date        DATE          NOT NULL,
    transaction_at          TIMESTAMPTZ,                     -- full timestamp, when the source provides one
    is_duplicate_in_source  BOOLEAN       NOT NULL DEFAULT FALSE,
    raw_values              JSONB         NOT NULL,          -- the original row, untouched
    created_at              TIMESTAMPTZ   NOT NULL DEFAULT now(),
    PRIMARY KEY (id, transaction_date),
    -- Stops a retried import inserting the same source row twice.
    UNIQUE (batch_id, source_row_number, transaction_date)
) PARTITION BY RANGE (transaction_date);

-- Indexes on the parent are created on every partition automatically.
CREATE INDEX transaction_record_match_idx ON transaction_record
    (organization_id, source_type, transaction_date, normalized_reference);
CREATE INDEX transaction_record_batch_idx ON transaction_record (organization_id, batch_id);

-- Creates the partition for the month containing p_month. Idempotent, so
-- the scheduled partition-maintenance job can call it every day.
CREATE FUNCTION create_transaction_record_partition(p_month DATE) RETURNS void
LANGUAGE plpgsql AS $$
DECLARE
    v_start DATE := date_trunc('month', p_month)::date;
    v_end   DATE := (date_trunc('month', p_month) + INTERVAL '1 month')::date;
    v_name  TEXT := format('transaction_record_%s', to_char(v_start, 'YYYY_MM'));
BEGIN
    EXECUTE format(
        'CREATE TABLE IF NOT EXISTS %I PARTITION OF transaction_record FOR VALUES FROM (%L) TO (%L)',
        v_name, v_start, v_end);
END;
$$;

-- 12 months back (historical imports) to 3 months ahead. The maintenance
-- job keeps extending the window; this just gives a working start.
DO $$
BEGIN
    PERFORM create_transaction_record_partition(m::date)
    FROM generate_series(date_trunc('month', now()) - INTERVAL '12 months',
                         date_trunc('month', now()) + INTERVAL '3 months',
                         INTERVAL '1 month') AS m;
END;
$$;

-- Catches rows outside every monthly partition. Alert if it is ever
-- non-empty: a monthly partition can't be created for a range while
-- rows for that range sit here.
CREATE TABLE transaction_record_default PARTITION OF transaction_record DEFAULT;


-- ---------------------------------------------------------------------
-- 4. Reconciliation
-- ---------------------------------------------------------------------

CREATE TABLE reconciliation_run (
    id                      UUID          PRIMARY KEY,
    organization_id         UUID          NOT NULL REFERENCES organization (id),
    idempotency_key         TEXT          NOT NULL,
    period_start            DATE          NOT NULL,
    period_end              DATE          NOT NULL,          -- inclusive
    left_source             TEXT          NOT NULL DEFAULT 'INTERNAL_LEDGER'
                                          CHECK (left_source IN ('INTERNAL_LEDGER', 'GATEWAY')),
    right_source            TEXT          NOT NULL DEFAULT 'GATEWAY'
                                          CHECK (right_source IN ('INTERNAL_LEDGER', 'GATEWAY')),
    -- v1 assumption: a run covers one currency, so its totals can be
    -- summed meaningfully. See the open question in README.md.
    currency                CHAR(3)       NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
    status                  TEXT          NOT NULL DEFAULT 'PENDING'
                                          CHECK (status IN ('PENDING', 'RUNNING', 'COMPLETED', 'FAILED')),
    last_completed_date     DATE,                            -- resume checkpoint: runs are chunked by day
    matched_count           INT           NOT NULL DEFAULT 0,
    matched_amount          NUMERIC(19,4) NOT NULL DEFAULT 0,
    mismatch_count          INT           NOT NULL DEFAULT 0,
    mismatch_net_difference NUMERIC(19,4) NOT NULL DEFAULT 0,
    unmatched_left_count    INT           NOT NULL DEFAULT 0,
    unmatched_left_amount   NUMERIC(19,4) NOT NULL DEFAULT 0,
    unmatched_right_count   INT           NOT NULL DEFAULT 0,
    unmatched_right_amount  NUMERIC(19,4) NOT NULL DEFAULT 0,
    duplicate_count         INT           NOT NULL DEFAULT 0,
    failure_reason          TEXT,
    triggered_by            UUID          NOT NULL REFERENCES app_user (id),
    started_at              TIMESTAMPTZ,
    completed_at            TIMESTAMPTZ,
    created_at              TIMESTAMPTZ   NOT NULL DEFAULT now(),
    updated_at              TIMESTAMPTZ   NOT NULL DEFAULT now(),
    UNIQUE (organization_id, idempotency_key),
    CHECK (period_end >= period_start),
    CHECK (left_source <> right_source)
);

CREATE INDEX reconciliation_run_list_idx ON reconciliation_run (organization_id, created_at DESC);

-- Foreign keys to transaction_record must reference its full primary
-- key, so each record id travels with its transaction_date.
-- Archival note: a monthly partition can't be detached while matches or
-- exception links still reference its rows; archive those first.
CREATE TABLE reconciliation_match (
    id                 UUID          PRIMARY KEY,
    organization_id    UUID          NOT NULL REFERENCES organization (id),
    run_id             UUID          NOT NULL REFERENCES reconciliation_run (id),
    ledger_record_id   UUID          NOT NULL,
    ledger_txn_date    DATE          NOT NULL,
    gateway_record_id  UUID          NOT NULL,
    gateway_txn_date   DATE          NOT NULL,
    match_type         TEXT          NOT NULL DEFAULT 'EXACT' CHECK (match_type IN ('EXACT')),
    amount_difference  NUMERIC(19,4) NOT NULL DEFAULT 0,     -- always 0 for EXACT; fee-aware matching (v2) uses it
    created_at         TIMESTAMPTZ   NOT NULL DEFAULT now(),
    FOREIGN KEY (ledger_record_id, ledger_txn_date)   REFERENCES transaction_record (id, transaction_date),
    FOREIGN KEY (gateway_record_id, gateway_txn_date) REFERENCES transaction_record (id, transaction_date),
    -- A record can be matched at most once per run.
    UNIQUE (run_id, ledger_record_id),
    UNIQUE (run_id, gateway_record_id)
);

CREATE INDEX reconciliation_match_ledger_idx  ON reconciliation_match (ledger_record_id);
CREATE INDEX reconciliation_match_gateway_idx ON reconciliation_match (gateway_record_id);


-- ---------------------------------------------------------------------
-- 5. Exceptions
-- ---------------------------------------------------------------------

CREATE TABLE exception_case (
    id                 UUID          PRIMARY KEY,
    organization_id    UUID          NOT NULL REFERENCES organization (id),
    run_id             UUID          NOT NULL REFERENCES reconciliation_run (id),   -- the run that raised it
    type               TEXT          NOT NULL
                                     CHECK (type IN ('MISSING_IN_GATEWAY', 'MISSING_IN_LEDGER', 'AMOUNT_MISMATCH',
                                                     'CURRENCY_MISMATCH', 'DUPLICATE_IN_SOURCE')),
    reason_code        TEXT,
    -- Deterministic identity of the discrepancy, e.g.
    -- 'AMOUNT_MISMATCH:PAY-103'. Re-running reconciliation computes the
    -- same key, which is what stops duplicate active cases.
    discrepancy_key    TEXT          NOT NULL,
    status             TEXT          NOT NULL DEFAULT 'OPEN'
                                     CHECK (status IN ('OPEN', 'IN_REVIEW', 'RESOLVED')),
    currency           CHAR(3)       NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
    amount_difference  NUMERIC(19,4),                        -- set for AMOUNT_MISMATCH
    assigned_to        UUID          REFERENCES app_user (id),
    resolution_code    TEXT,
    resolution_note    TEXT,
    resolved_by        UUID          REFERENCES app_user (id),
    resolved_at        TIMESTAMPTZ,
    version            BIGINT        NOT NULL DEFAULT 0,     -- optimistic locking (@Version)
    created_at         TIMESTAMPTZ   NOT NULL DEFAULT now(),
    updated_at         TIMESTAMPTZ   NOT NULL DEFAULT now(),
    -- Resolution fields are set exactly when the case is RESOLVED. A
    -- reopen clears them; the earlier resolution survives in
    -- exception_status_history.
    CHECK ((status = 'RESOLVED') =
           (resolution_code IS NOT NULL AND resolved_by IS NOT NULL AND resolved_at IS NOT NULL))
);

-- At most one active case per discrepancy, enforced by the database so
-- two concurrent runs can't both insert one.
CREATE UNIQUE INDEX exception_case_active_uk ON exception_case (organization_id, discrepancy_key)
    WHERE status <> 'RESOLVED';
CREATE INDEX exception_case_list_idx     ON exception_case (organization_id, status, created_at DESC);
CREATE INDEX exception_case_assignee_idx ON exception_case (organization_id, assigned_to, status)
    WHERE assigned_to IS NOT NULL;
CREATE INDEX exception_case_run_idx      ON exception_case (run_id);

-- Links a case to every record involved. A link table rather than two
-- FK columns, because a duplicate can involve three or more records.
CREATE TABLE exception_case_record (
    exception_id           UUID NOT NULL REFERENCES exception_case (id),
    transaction_record_id  UUID NOT NULL,
    transaction_date       DATE NOT NULL,
    organization_id        UUID NOT NULL REFERENCES organization (id),
    PRIMARY KEY (exception_id, transaction_record_id),
    FOREIGN KEY (transaction_record_id, transaction_date) REFERENCES transaction_record (id, transaction_date)
);

CREATE INDEX exception_case_record_txn_idx ON exception_case_record (transaction_record_id);

CREATE TABLE exception_note (
    id               UUID        PRIMARY KEY,
    organization_id  UUID        NOT NULL REFERENCES organization (id),
    exception_id     UUID        NOT NULL REFERENCES exception_case (id),
    author_id        UUID        NOT NULL REFERENCES app_user (id),
    body             TEXT        NOT NULL CHECK (length(btrim(body)) > 0),
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX exception_note_exception_idx ON exception_note (exception_id, created_at);

-- Queryable domain history of every status change. audit_event records
-- the same change for compliance; this table answers "what happened to
-- this case" without parsing audit payloads.
CREATE TABLE exception_status_history (
    id               UUID        PRIMARY KEY,
    organization_id  UUID        NOT NULL REFERENCES organization (id),
    exception_id     UUID        NOT NULL REFERENCES exception_case (id),
    from_status      TEXT,                                   -- NULL when the case is created
    to_status        TEXT        NOT NULL CHECK (to_status IN ('OPEN', 'IN_REVIEW', 'RESOLVED')),
    reason           TEXT,
    resolution_code  TEXT,                                   -- copied here so a reopen doesn't lose it
    resolution_note  TEXT,
    actor_id         UUID        REFERENCES app_user (id),   -- NULL for system transitions
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX exception_status_history_exception_idx ON exception_status_history (exception_id, created_at);
